style.css:
body {
  margin: 0;
  min-height: 100vh;

  /* Background image */
  background-image: url("https://i.pinimg.com/736x/34/91/7f/34917fbdaccc1c80d054b371c65d61e8.jpg");

  /* Make it look nice */
  background-size: cover;        /* scale image to cover screen */
  background-position: center;   /* keep it centered */
  background-repeat: no-repeat;  /* avoid tiling */
}
